#!/bin/bash
# Build core-image-aesd.
# Usage: ./build.sh [MACHINE]    e.g. ./build.sh qemuarm64   (default: raspberrypi4-64)
# - Generated by Claude.ai -
# Prompt:
# "can you explain what this [original build.sh] script does,
# and how/if I should edit it to include other layers/packages (like meta-raspberrypi)?"
# (context of the project given)

MACHINE_NAME="${1:-raspberrypi4-64}"

git submodule init
git submodule sync
git submodule update

source poky/oe-init-build-env   # creates/enters build/

set -e

add_layer() {
    if bitbake-layers show-layers | grep -q "$(basename "$1")"; then
        echo "$1 already present"
    else
        echo "Adding $1"
        bitbake-layers add-layer "$1"
    fi
}

# Remove any existing hard assignment of VAR, then append the new one.
# Safe to re-run and safe when changing values. Leaves '??=' defaults alone.
set_conf() {
    sed -i "/^$1 *=/d" conf/local.conf
    echo "$1 = \"$2\"" >> conf/local.conf
}

# Layers BEFORE MACHINE
add_layer ../meta-raspberrypi
add_layer ../meta-aesd

set_conf MACHINE "$MACHINE_NAME"

if [[ "$MACHINE_NAME" == raspberrypi* ]]; then
    set_conf ENABLE_UART 1                                  # serial console for debugging
    set_conf ENABLE_DWC2_PERIPHERAL 1                       # USB gadget mode
    set_conf LICENSE_FLAGS_ACCEPTED "synaptics-killswitch"  # needed for Pi Wi-Fi firmware
fi

bitbake core-image-aesd
